SELECT COALESCE(SUM(qty - locked_qty), 0) FROM mis_residual_inventory WHERE material_id = #{materialId}
AND warehouse_id = #{warehouseId}
AND status IN ('AVAILABLE', 'LOCKED') AND (qty - locked_qty) > 0 AND del_flag = '0'

SELECT * FROM mis_residual_inventory WHERE material_id = #{materialId}
AND warehouse_id = #{warehouseId}
AND status IN ('AVAILABLE', 'LOCKED') AND (qty - locked_qty) > 0 AND del_flag = '0' ORDER BY create_time ASC
